-- =====================
-- DROP para recrear limpio
-- =====================

DROP TABLE IF EXISTS historico_ubicacion_geografica;
DROP TABLE IF EXISTS historico_ruta;
DROP TABLE IF EXISTS piso_lugar;
DROP TABLE IF EXISTS lugar_ruta;
DROP TABLE IF EXISTS imagen;
DROP TABLE IF EXISTS lugar;
DROP TABLE IF EXISTS ruta;
DROP TABLE IF EXISTS campus;
DROP TABLE IF EXISTS ubicacion_geografica;
DROP TABLE IF EXISTS tipo_lugar;
DROP TABLE IF EXISTS estado_ubicacion_geografica;
DROP TABLE IF EXISTS tipo_geojson;
DROP TABLE IF EXISTS usuario;
DROP TABLE IF EXISTS sugerencia;


CREATE TABLE tipo_lugar(
  id_tipo_lugar INTEGER NOT NULL PRIMARY KEY, 
  nombre_tipo_lugar VARCHAR NOT NULL,
  icono VARCHAR NOT NULL,
  color_icono VARCHAR
);


CREATE TABLE piso_lugar(
  id_piso_lugar INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
  numero_piso INTEGER NOT NULL,
  fk_id_lugar INTEGER NOT NULL,
  CONSTRAINT lugar_piso_lugar
    FOREIGN KEY (fk_id_lugar) REFERENCES lugar (id_lugar)
);


CREATE TABLE lugar(
  id_lugar INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
  nombre_lugar VARCHAR NOT NULL,
  arquitecto VARCHAR,
  premio VARCHAR,
  fecha DATE,
  facultad VARCHAR,
  fk_id_tipo_lugar INTEGER NOT NULL,
  fk_id_ubicacion_geografica INTEGER NOT NULL,
  fk_id_campus INTEGER NOT NULL,
  CONSTRAINT tipo_lugar_lugar
    FOREIGN KEY (fk_id_tipo_lugar) 
      REFERENCES tipo_lugar (id_tipo_lugar),
  CONSTRAINT ubicacion_geografica_lugar
    FOREIGN KEY (fk_id_ubicacion_geografica)
      REFERENCES ubicacion_geografica (id_ubicacion_geografica),
  CONSTRAINT campus_lugar FOREIGN KEY (fk_id_campus) REFERENCES campus (id_campus)
);


CREATE TABLE campus(
  id_campus INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
  nombre_campus VARCHAR NOT NULL,
  fk_id_ubicacion_geografica INTEGER NOT NULL,
  CONSTRAINT ubicacion_geografica_campus
    FOREIGN KEY (fk_id_ubicacion_geografica)
      REFERENCES ubicacion_geografica (id_ubicacion_geografica)
);


CREATE TABLE ubicacion_geografica(
  id_ubicacion_geografica INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
  descripcion VARCHAR,
  fecha_creacion DATETIME NOT NULL,
  geojson JSON NOT NULL,
  fk_id_estado_ubicacion_geografica INTEGER NOT NULL,
  fk_id_tipo_geojson INTEGER NOT NULL,
  CONSTRAINT estado_ubicacion_geografica_ubicacion_geografica
    FOREIGN KEY (fk_id_estado_ubicacion_geografica)
      REFERENCES estado_ubicacion_geografica (id_estado_ubicacion_geografica),
  CONSTRAINT tipo_geojson_ubicacion_geografica
    FOREIGN KEY (fk_id_tipo_geojson) 
      REFERENCES tipo_geojson (id_tipo_geojson)
);


CREATE TABLE tipo_geojson(
id_tipo_geojson INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
  nombre_tipo_geojson VARCHAR NOT NULL
);


CREATE TABLE estado_ubicacion_geografica(
id_estado_ubicacion_geografica INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
  nombre_estado VARCHAR NOT NULL
);


CREATE TABLE ruta(
  id_ruta INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
  nombre_ruta VARCHAR NOT NULL,
  fk_id_ubicacion_geografica INTEGER NOT NULL,
  fk_id_campus INTEGER NOT NULL,
  icono VARCHAR,
  color_icono VARCHAR,
  CONSTRAINT campus_ruta
    FOREIGN KEY (fk_id_campus) REFERENCES campus (id_campus),
  CONSTRAINT ubicacion_geografica_ruta
    FOREIGN KEY (fk_id_ubicacion_geografica)
      REFERENCES ubicacion_geografica (id_ubicacion_geografica)
);


CREATE TABLE lugar_ruta(
  id_lugar_ruta INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
  fk_id_ruta INTEGER NOT NULL,
  fk_id_lugar INTEGER NOT NULL,
  CONSTRAINT ruta_union_ruta_lugar
    FOREIGN KEY (fk_id_ruta) REFERENCES ruta (id_ruta),
  CONSTRAINT lugar_union_ruta_lugar
    FOREIGN KEY (fk_id_lugar) REFERENCES lugar (id_lugar)
);


CREATE TABLE imagen(
  id_imagen INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
  descripcion VARCHAR(2500) NULL,
  binario BLOB NOT NULL,
  fk_id_ubicacion_geografica INTEGER NOT NULL,
  mime_type VARCHAR(50) NULL,
  CONSTRAINT ubicacion_geografica_imagen
    FOREIGN KEY (fk_id_ubicacion_geografica)
      REFERENCES ubicacion_geografica (id_ubicacion_geografica)
);


CREATE TABLE sugerencia(
  id_sugerencia INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
  email VARCHAR NOT NULL,
  sugerencia VARCHAR NOT NULL,
  nombres VARCHAR NOT NULL,
  apellidos VARCHAR NOT NULL
);


CREATE TABLE usuario(
  id_usuario INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
  rut VARCHAR NOT NULL,
  dv CHARACTER NOT NULL,
  email VARCHAR NOT NULL,
  uid VARCHAR NOT NULL,
  nombres VARCHAR NOT NULL,
  apellidos VARCHAR NOT NULL
);

CREATE TABLE historico_ubicacion_geografica(
  id_historico_ubicacion INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
  nombre_usuario VARCHAR NOT NULL,
  tipo_operacion VARCHAR(20) NOT NULL,
  mensaje VARCHAR NOT NULL,
  fk_id_ubicacion_geografica INTEGER NOT NULL,
  fecha DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT historico_ubicacion_geografica
    FOREIGN KEY (fk_id_ubicacion_geografica)
      REFERENCES ubicacion_geografica (id_ubicacion_geografica)
);

CREATE TABLE historico_ruta(
  id_historico_ruta INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
  nombre_usuario VARCHAR NOT NULL,
  tipo_operacion VARCHAR(20) NOT NULL,
  mensaje VARCHAR NOT NULL,
  fk_id_ruta INTEGER NOT NULL,
  fecha DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT historico_ruta_fk
    FOREIGN KEY (fk_id_ruta)
      REFERENCES ruta (id_ruta)
);

